// Minimal PostgreSQL client (wire protocol v3, simple query, SCRAM/MD5/cleartext auth).
const net = require('net');
const crypto = require('crypto');

const md5 = (s) => crypto.createHash('md5').update(s).digest('hex');
const hmac = (k, s) => crypto.createHmac('sha256', k).update(s).digest();
const sha256 = (s) => crypto.createHash('sha256').update(s).digest();

class Conn {
  constructor(opts) {
    this.opts = opts;
    this.buf = Buffer.alloc(0);
    this.dead = false;
    this.busy = false;
    this.current = null; // in-flight query
    this.connectWaiter = null;
  }

  connect() {
    return new Promise((resolve, reject) => {
      this.connectWaiter = { resolve, reject };
      this.sock = net.connect(this.opts.port, this.opts.host);
      this.sock.setNoDelay(true);
      this.sock.on('connect', () => {
        const params = Buffer.from(`user\0${this.opts.user}\0database\0${this.opts.database}\0\0`);
        const head = Buffer.alloc(8);
        head.writeInt32BE(8 + params.length, 0);
        head.writeInt32BE(196608, 4);
        this.sock.write(Buffer.concat([head, params]));
      });
      this.sock.on('data', (d) => this.onData(d));
      this.sock.on('error', (e) => this.fail(e));
      this.sock.on('close', () => this.fail(new Error('connection closed')));
    });
  }

  fail(err) {
    if (this.dead) return;
    this.dead = true;
    if (this.connectWaiter) { const w = this.connectWaiter; this.connectWaiter = null; w.reject(err); }
    if (this.current) { const c = this.current; this.current = null; c.reject(err); }
    try { this.sock.destroy(); } catch (e) { /* ignore */ }
  }

  send(type, body) {
    const head = Buffer.alloc(5);
    head.write(type, 0, 'ascii');
    head.writeInt32BE(4 + body.length, 1);
    this.sock.write(Buffer.concat([head, body]));
  }

  sendPassword(str) {
    this.send('p', Buffer.from(str + '\0'));
  }

  onData(d) {
    this.buf = this.buf.length ? Buffer.concat([this.buf, d]) : d;
    while (this.buf.length >= 5) {
      const type = String.fromCharCode(this.buf[0]);
      const len = this.buf.readInt32BE(1);
      if (this.buf.length < 1 + len) break;
      const body = this.buf.subarray(5, 1 + len);
      this.buf = this.buf.subarray(1 + len);
      try {
        this.handle(type, body);
      } catch (e) {
        this.fail(e);
        return;
      }
    }
  }

  handle(type, body) {
    switch (type) {
      case 'R': return this.onAuth(body);
      case 'E': {
        const err = parseError(body);
        if (this.connectWaiter) { const w = this.connectWaiter; this.connectWaiter = null; this.sock.destroy(); this.dead = true; w.reject(new Error(err)); return; }
        if (this.current) this.current.error = err;
        return;
      }
      case 'T': {
        const n = body.readInt16BE(0);
        let off = 2;
        const cols = [];
        for (let i = 0; i < n; i++) {
          const end = body.indexOf(0, off);
          cols.push(body.toString('utf8', off, end));
          off = end + 1 + 18;
        }
        this.current.cols = cols;
        this.current.rows = [];
        return;
      }
      case 'D': {
        const n = body.readInt16BE(0);
        let off = 2;
        const row = [];
        for (let i = 0; i < n; i++) {
          const len = body.readInt32BE(off);
          off += 4;
          if (len === -1) row.push(null);
          else { row.push(body.toString('utf8', off, off + len)); off += len; }
        }
        this.current.rows.push(row);
        return;
      }
      case 'Z': {
        if (this.connectWaiter) { const w = this.connectWaiter; this.connectWaiter = null; w.resolve(this); return; }
        const cur = this.current;
        this.current = null;
        this.busy = false;
        if (cur) {
          if (cur.error) cur.reject(new Error(cur.error));
          else cur.resolve({ cols: cur.cols || [], rows: cur.rows || [] });
        }
        return;
      }
      default:
        // 'S' parameter status, 'K' key data, 'C' command complete, 'N' notice, 'I' empty query: ignored
        return;
    }
  }

  onAuth(body) {
    const code = body.readInt32BE(0);
    const pw = this.opts.password;
    if (code === 0) return;
    if (code === 3) return this.sendPassword(pw);
    if (code === 5) {
      const salt = body.subarray(4, 8);
      const inner = md5(pw + this.opts.user);
      return this.sendPassword('md5' + md5(Buffer.concat([Buffer.from(inner), salt])));
    }
    if (code === 10) {
      this.scram = { nonce: crypto.randomBytes(18).toString('base64') };
      this.scram.clientFirstBare = `n=,r=${this.scram.nonce}`;
      const clientFirst = 'n,,' + this.scram.clientFirstBare;
      const cf = Buffer.from(clientFirst);
      const mech = Buffer.from('SCRAM-SHA-256\0');
      const body2 = Buffer.alloc(mech.length + 4 + cf.length);
      mech.copy(body2, 0);
      body2.writeInt32BE(cf.length, mech.length);
      cf.copy(body2, mech.length + 4);
      return this.send('p', body2);
    }
    if (code === 11) {
      const serverFirst = body.toString('utf8', 4);
      const attrs = Object.fromEntries(serverFirst.split(',').map((p) => [p[0], p.slice(2)]));
      if (!attrs.r.startsWith(this.scram.nonce)) throw new Error('bad scram nonce');
      const salt = Buffer.from(attrs.s, 'base64');
      const iter = parseInt(attrs.i, 10);
      const salted = crypto.pbkdf2Sync(pw, salt, iter, 32, 'sha256');
      const clientKey = hmac(salted, 'Client Key');
      const storedKey = sha256(clientKey);
      const clientFinalNoProof = 'c=biws,r=' + attrs.r;
      const authMessage = this.scram.clientFirstBare + ',' + serverFirst + ',' + clientFinalNoProof;
      const clientSig = hmac(storedKey, authMessage);
      const proof = Buffer.from(clientKey.map((b, i) => b ^ clientSig[i])).toString('base64');
      this.scram.serverSig = hmac(hmac(salted, 'Server Key'), authMessage).toString('base64');
      return this.sendPassword(clientFinalNoProof + ',p=' + proof);
    }
    if (code === 12) {
      const final = body.toString('utf8', 4);
      if (final !== 'v=' + this.scram.serverSig) throw new Error('bad scram server signature');
      return;
    }
    throw new Error('unsupported auth method ' + code);
  }

  query(sql) {
    return new Promise((resolve, reject) => {
      this.busy = true;
      this.current = { resolve, reject, cols: null, rows: null, error: null };
      const q = Buffer.from(sql + '\0', 'utf8');
      const head = Buffer.alloc(5);
      head.write('Q', 0, 'ascii');
      head.writeInt32BE(4 + q.length, 1);
      this.sock.write(Buffer.concat([head, q]));
    });
  }
}

function parseError(body) {
  let off = 0;
  const fields = {};
  while (off < body.length && body[off] !== 0) {
    const code = String.fromCharCode(body[off]);
    const end = body.indexOf(0, off + 1);
    fields[code] = body.toString('utf8', off + 1, end);
    off = end + 1;
  }
  return fields.M || 'database error';
}

class Pool {
  constructor(opts, size) {
    this.opts = opts;
    this.size = size;
    this.conns = [];
    this.waiters = [];
  }

  async acquire() {
    const idle = this.conns.find((c) => !c.busy && !c.dead && !c.leased);
    if (idle) { idle.leased = true; return idle; }
    if (this.conns.length < this.size) {
      const c = new Conn(this.opts);
      this.conns.push(c);
      try {
        await c.connect();
      } catch (e) {
        this.conns = this.conns.filter((x) => x !== c);
        this.release(null);
        throw e;
      }
      c.leased = true;
      return c;
    }
    return new Promise((resolve) => this.waiters.push(resolve));
  }

  release(c) {
    if (c) {
      c.leased = false;
      if (c.dead) this.conns = this.conns.filter((x) => x !== c);
    }
    const w = this.waiters.shift();
    if (w) {
      // hand a connection (or a free slot) to the next waiter
      const idle = this.conns.find((x) => !x.busy && !x.dead && !x.leased);
      if (idle) { idle.leased = true; w(idle); }
      else if (this.conns.length < this.size) {
        this.waiters.unshift(w);
        this.acquire().then((conn) => { const ww = this.waiters.shift(); if (ww) ww(conn); else this.release(conn); }).catch(() => {});
      } else this.waiters.unshift(w);
    }
  }

  // Runs fn(conn) on a dedicated connection; conn.query(sql) runs statements in order.
  async with(fn) {
    const c = await this.acquire();
    try {
      return await fn(c);
    } finally {
      this.release(c);
    }
  }

  query(sql) {
    return this.with((c) => c.query(sql));
  }
}

// SQL literal helpers (standard_conforming_strings is on by default).
function lit(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number') { if (!Number.isInteger(v)) throw new Error('non-integer'); return String(v); }
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE';
  const s = String(v);
  if (s.includes('\0')) throw new Error('NUL in string');
  return "'" + s.replace(/'/g, "''") + "'";
}

module.exports = { Pool, lit };
