// Bookshop HTTP API on :8089, backed by PostgreSQL (see pg.js).
const http = require('http');
const { Pool, lit } = require('./pg');

const PORT = 8089;
const PAYMENT_URL = 'http://127.0.0.1:18090/payments';
const INT4_MAX = 2147483647;

const pool = new Pool({ host: 'postgres', port: 5432, user: 'eval_rw', password: 'eval_rw', database: 'llmapi_eval' }, 10);

class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}
const fail = (status, message) => {
  throw new HttpError(status, message);
};

function sendJson(res, status, body) {
  if (body === undefined) {
    res.writeHead(status);
    res.end();
    return;
  }
  const s = JSON.stringify(body);
  res.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Content-Length': Buffer.byteLength(s) });
  res.end(s);
}

// ---- parsing helpers ----

// Ids in paths and headers: plain digits within int4 range, otherwise null (-> not found / unauthorized).
function parseId(s) {
  if (typeof s !== 'string' || !/^\d+$/.test(s)) return null;
  const n = Number(s);
  return n >= 1 && n <= INT4_MAX ? n : null;
}

// Integer query parameter within [min, max]; malformed or out of range -> 400.
function intParam(s, min, max, name) {
  if (!/^\d+$/.test(s) || Number(s) < min || Number(s) > max) fail(400, `invalid ${name}`);
  return Number(s);
}

function paging(sp) {
  const page = sp.has('page') ? intParam(sp.get('page'), 1, 1e9, 'page') : 1;
  const itemsPerPage = sp.has('itemsPerPage') ? intParam(sp.get('itemsPerPage'), 1, 50, 'itemsPerPage') : 10;
  return { page, itemsPerPage, offset: (page - 1) * itemsPerPage };
}

function dateParam(s) {
  if (typeof s !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(s)) return null;
  const d = new Date(s + 'T00:00:00Z');
  return Number.isNaN(d.getTime()) || d.toISOString().slice(0, 10) !== s ? null : s;
}

function isoPlusOneDay(day) {
  return new Date(Date.parse(day + 'T00:00:00Z') + 86400000).toISOString().slice(0, 10);
}

// Reads a JSON body; empty body yields `emptyValue`.
function readBody(req, emptyValue) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    req.on('data', (c) => {
      size += c.length;
      if (size > 1 << 20) {
        reject(new HttpError(413, 'body too large'));
        req.destroy();
        return;
      }
      chunks.push(c);
    });
    req.on('error', reject);
    req.on('end', () => {
      const text = Buffer.concat(chunks).toString('utf8').trim();
      if (text === '') return resolve(emptyValue);
      try {
        resolve(JSON.parse(text));
      } catch (e) {
        reject(new HttpError(400, 'invalid JSON body'));
      }
    });
  });
}

const isPlainObject = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);

// ---- SQL fragments ----

const TS = (col) => `to_char(${col} AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')`;
const DAY = (col) => `to_char(${col}, 'YYYY-MM-DD')`;

// JSON shape of one book (author joined as a)
const BOOK_JSON = `json_build_object('id', b.id, 'title', b.title, 'priceCents', b.price_cents, 'publishedAt', ${DAY('b.published_at')}, 'stock', b.stock, 'author', json_build_object('id', a.id, 'name', a.name))`;

// JSON shape of one purchase (p = purchase row)
const purchaseJson = (where) => `
SELECT json_build_object('id', p.id, 'createdAt', ${TS('p.created_at')}, 'totalCents', p.total_cents,
  'lines', (SELECT coalesce(json_agg(json_build_object('bookId', l.book_id, 'title', b.title, 'quantity', l.quantity, 'unitPriceCents', l.unit_price_cents) ORDER BY l.id), '[]'::json)
            FROM purchase_line l JOIN book b ON b.id = l.book_id WHERE l.purchase_id = p.id))
FROM purchase p WHERE ${where}`;

// Runs a SQL statement returning exactly one json value; returns the parsed value.
async function queryJson(conn, sql) {
  const r = await conn.query(sql);
  const v = r.rows.length ? r.rows[0][0] : null;
  return v === null ? null : JSON.parse(v);
}

// ---- authors ----

async function listAuthors(sp) {
  const { page, itemsPerPage, offset } = paging(sp);
  const sql = `SELECT json_build_object(
    'items', (SELECT coalesce(json_agg(t), '[]'::json) FROM (
        SELECT a.id, a.name, (SELECT count(*) FROM book b WHERE b.author_id = a.id AND b.published) AS "publishedBooks"
        FROM author a ORDER BY a.id LIMIT ${itemsPerPage} OFFSET ${offset}) t),
    'total', (SELECT count(*) FROM author))`;
  const body = await pool.with((c) => queryJson(c, sql));
  return { items: body.items, total: Number(body.total), page, itemsPerPage };
}

async function getAuthor(id) {
  const sql = `SELECT json_build_object('id', a.id, 'name', a.name, 'books',
    (SELECT coalesce(json_agg(json_build_object('id', b.id, 'title', b.title) ORDER BY b.id), '[]'::json)
     FROM book b WHERE b.author_id = a.id AND b.published))
    FROM author a WHERE a.id = ${id}`;
  return pool.with((c) => queryJson(c, sql));
}

// ---- books ----

const BOOK_ORDER_COLS = { priceCents: 'price_cents', title: 'title', publishedAt: 'published_at' };

async function listBooks(sp) {
  const { page, itemsPerPage, offset } = paging(sp);
  const where = ['TRUE'];

  if (sp.has('title')) where.push(`strpos(lower(b.title), lower(${lit(sp.get('title'))})) > 0`);
  if (sp.has('author')) where.push(`a.name = ${lit(sp.get('author'))}`);

  for (const [key, col] of [['priceCents', 'b.price_cents'], ['publishedAt', 'b.published_at']]) {
    for (const [op, sqlOp] of [['gte', '>='], ['lte', '<='], ['after', '>='], ['before', '<=']]) {
      const name = `${key}[${op}]`;
      if (!sp.has(name)) continue;
      const v = sp.get(name);
      if (key === 'priceCents') {
        if (!/^-?\d+$/.test(v) || !['gte', 'lte'].includes(op)) fail(400, `invalid ${name}`);
        where.push(`${col} ${sqlOp} ${v}`);
      } else {
        if (!['after', 'before'].includes(op)) continue;
        const d = dateParam(v);
        if (!d) fail(400, `invalid ${name}`);
        where.push(`${col} ${sqlOp} ${lit(d)}`);
      }
    }
  }

  if (sp.has('inStock')) {
    const v = sp.get('inStock');
    if (v === 'true') where.push('b.stock > 0');
    else if (v === 'false') where.push('b.stock = 0');
    else fail(400, 'invalid inStock');
  }

  const orders = [];
  for (const [k, v] of sp) {
    const m = /^order\[(\w+)\]$/.exec(k);
    if (!m) continue;
    if (!Object.prototype.hasOwnProperty.call(BOOK_ORDER_COLS, m[1])) fail(400, `invalid sort field ${m[1]}`);
    if (v !== 'asc' && v !== 'desc') fail(400, 'invalid sort direction');
    orders.push(`${BOOK_ORDER_COLS[m[1]]}${m[1] === "title" ? x27 COLLATE "C"x27 : ""} ${v.toUpperCase()}`);
  }
  orders.push('id ASC');

  const sql = `WITH base AS (
      SELECT b.id, b.title, b.price_cents, b.published_at, b.stock, a.id AS author_id, a.name AS author_name
      FROM book b JOIN author a ON a.id = b.author_id
      WHERE b.published AND ${where.join(' AND ')})
    SELECT json_build_object(
      'total', (SELECT count(*) FROM base),
      'items', (SELECT coalesce(json_agg(t), '[]'::json) FROM (
          SELECT id, title, price_cents AS "priceCents", to_char(published_at, 'YYYY-MM-DD') AS "publishedAt", stock,
                 json_build_object('id', author_id, 'name', author_name) AS author
          FROM base ORDER BY ${orders.join(', ')} LIMIT ${itemsPerPage} OFFSET ${offset}) t))`;
  const body = await pool.with((c) => queryJson(c, sql));
  return { items: body.items, total: Number(body.total), page, itemsPerPage };
}

async function getBook(conn, id) {
  return queryJson(conn, `SELECT ${BOOK_JSON} FROM book b JOIN author a ON a.id = b.author_id WHERE b.id = ${id} AND b.published`);
}

async function patchBook(id, input) {
  const sets = [];
  const body = isPlainObject(input) ? input : null;
  if (!body) fail(422, 'body must be an object');
  if ('title' in body) {
    if (typeof body.title !== 'string' || body.title.trim() === '') fail(422, 'invalid title');
    sets.push(`title = ${lit(body.title)}`);
  }
  if ('priceCents' in body) {
    if (!Number.isInteger(body.priceCents) || body.priceCents < 0 || body.priceCents > INT4_MAX) fail(422, 'invalid priceCents');
    sets.push(`price_cents = ${body.priceCents}`);
  }
  if ('stock' in body) {
    if (!Number.isInteger(body.stock) || body.stock < 0 || body.stock > INT4_MAX) fail(422, 'invalid stock');
    sets.push(`stock = ${body.stock}`);
  }
  return pool.with(async (c) => {
    const exists = await c.query(`SELECT 1 FROM book WHERE id = ${id}`);
    if (exists.rows.length === 0) fail(404, 'book not found');
    if (sets.length) await c.query(`UPDATE book SET ${sets.join(', ')} WHERE id = ${id}`);
    const pub = await c.query(`SELECT published FROM book WHERE id = ${id}`);
    if (pub.rows[0][0] !== 't') return null;
    return getBook(c, id);
  });
}

// ---- purchases ----

async function customerExists(customerId) {
  const r = await pool.query(`SELECT 1 FROM customer WHERE id = ${customerId}`);
  return r.rows.length > 0;
}

async function listPurchases(customerId, sp) {
  const { page, itemsPerPage, offset } = paging(sp);
  const ids = await pool.query(`SELECT p.id FROM purchase p WHERE p.customer_id = ${customerId}
    ORDER BY p.created_at DESC, p.id DESC LIMIT ${itemsPerPage} OFFSET ${offset}`);
  const total = await pool.query(`SELECT count(*) FROM purchase WHERE customer_id = ${customerId}`);
  const items = await pool.with(async (c) => {
    const out = [];
    for (const [id] of ids.rows) out.push(await queryJson(c, purchaseJson(`p.id = ${id}`)));
    return out;
  });
  return { items, total: Number(total.rows[0][0]), page, itemsPerPage };
}

async function getPurchase(customerId, id) {
  return pool.with((c) => queryJson(c, purchaseJson(`p.id = ${id} AND p.customer_id = ${customerId}`)));
}

// Calls the payment service: 'accepted' | 'declined'; anything else throws.
async function charge(customerId, amountCents) {
  let res;
  try {
    res = await fetch(PAYMENT_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ customerId, amountCents }),
      signal: AbortSignal.timeout(5000),
    });
  } catch (e) {
    fail(502, 'payment service unreachable');
  }
  if (!res.ok) fail(502, 'payment service failed');
  let data;
  try {
    data = await res.json();
  } catch (e) {
    fail(502, 'payment service invalid response');
  }
  if (isPlainObject(data) && data.status === 'accepted') return 'accepted';
  if (isPlainObject(data) && data.status === 'declined') return 'declined';
  fail(502, 'payment service invalid response');
}

function parseLines(input) {
  if (!isPlainObject(input) || !Array.isArray(input.lines) || input.lines.length === 0) fail(422, 'lines must be a non-empty array');
  return input.lines.map((l) => {
    if (!isPlainObject(l)) fail(422, 'invalid line');
    if (!Number.isInteger(l.bookId) || l.bookId < 1 || l.bookId > INT4_MAX) fail(422, 'invalid bookId');
    if (!Number.isInteger(l.quantity) || l.quantity < 1 || l.quantity > INT4_MAX) fail(422, 'invalid quantity');
    return { bookId: l.bookId, quantity: l.quantity };
  });
}

async function createPurchase(customerId, lines) {
  const ids = [...new Set(lines.map((l) => l.bookId))].sort((a, b) => a - b);
  return pool.with(async (c) => {
    await c.query('BEGIN');
    try {
      // Lock the books (in id order) so that stock checks and updates are race-free.
      const found = await c.query(`SELECT id, price_cents, stock, published FROM book WHERE id IN (${ids.join(', ')}) ORDER BY id FOR UPDATE`);
      const books = new Map(found.rows.map((r) => [Number(r[0]), { price: Number(r[1]), stock: Number(r[2]), published: r[3] === 't' }]));

      const wanted = new Map();
      for (const l of lines) {
        const b = books.get(l.bookId);
        if (!b || !b.published) fail(422, `book ${l.bookId} is not available`);
        wanted.set(l.bookId, (wanted.get(l.bookId) || 0) + l.quantity);
      }
      for (const [bookId, qty] of wanted) {
        if (books.get(bookId).stock < qty) fail(409, `not enough stock for book ${bookId}`);
      }

      const priced = lines.map((l) => ({ bookId: l.bookId, quantity: l.quantity, unitPrice: books.get(l.bookId).price }));
      const total = priced.reduce((s, l) => s + l.quantity * l.unitPrice, 0);

      const verdict = await charge(customerId, total);
      if (verdict === 'declined') fail(402, 'payment declined');

      const ins = await c.query(`INSERT INTO purchase (customer_id, created_at, total_cents) VALUES (${customerId}, now(), ${total}) RETURNING id`);
      const purchaseId = Number(ins.rows[0][0]);
      await c.query(`INSERT INTO purchase_line (purchase_id, book_id, quantity, unit_price_cents) VALUES ${priced
        .map((l) => `(${purchaseId}, ${l.bookId}, ${l.quantity}, ${l.unitPrice})`)
        .join(', ')}`);
      for (const [bookId, qty] of wanted) {
        await c.query(`UPDATE book SET stock = stock - ${qty} WHERE id = ${bookId}`);
      }
      const result = await queryJson(c, purchaseJson(`p.id = ${purchaseId}`));
      await c.query('COMMIT');
      return result;
    } catch (e) {
      await c.query('ROLLBACK').catch(() => {});
      throw e;
    }
  });
}

// ---- reports ----

async function salesReport(sp) {
  const from = dateParam(sp.get('from'));
  const to = dateParam(sp.get('to'));
  if (!from || !to || from > to) fail(400, 'from and to are required dates, from <= to');
  const sql = `SELECT b.title, sum(l.quantity) AS quantity, sum(l.quantity * l.unit_price_cents) AS revenue, b.id
    FROM purchase_line l
    JOIN purchase p ON p.id = l.purchase_id
    JOIN book b ON b.id = l.book_id
    WHERE p.created_at >= ${lit(from + 'T00:00:00Z')}::timestamptz AND p.created_at < ${lit(isoPlusOneDay(to) + 'T00:00:00Z')}::timestamptz
    GROUP BY b.id, b.title`;
  const r = await pool.query(sql);
  const rows = r.rows.map((x) => ({ title: x[0], quantity: Number(x[1]), revenueCents: Number(x[2]), id: Number(x[3]) }));
  rows.sort((a, b) => b.revenueCents - a.revenueCents || (a.title < b.title ? -1 : a.title > b.title ? 1 : 0) || a.id - b.id);
  const csvCell = (v) => {
    const s = String(v);
    return /[",\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  };
  const lines = ['title,quantity,revenueCents', ...rows.map((x) => [x.title, x.quantity, x.revenueCents].map(csvCell).join(','))];
  return lines.join('\n') + '\n';
}

// ---- routing ----

async function route(req, res) {
  const url = new URL(req.url, 'http://localhost');
  const parts = url.pathname.split('/').filter((p) => p !== '');
  const sp = url.searchParams;
  const method = req.method;
  const notFound = () => fail(404, 'not found');

  if (parts[0] === 'authors' && parts.length <= 2) {
    if (method !== 'GET') fail(405, 'method not allowed');
    if (parts.length === 1) return sendJson(res, 200, await listAuthors(sp));
    const id = parseId(parts[1]);
    const author = id && (await getAuthor(id));
    if (!author) notFound();
    return sendJson(res, 200, author);
  }

  if (parts[0] === 'books' && parts.length <= 2) {
    if (parts.length === 1) {
      if (method !== 'GET') fail(405, 'method not allowed');
      return sendJson(res, 200, await listBooks(sp));
    }
    const id = parseId(parts[1]);
    if (!id) notFound();
    if (method === 'GET') {
      const book = await pool.with((c) => getBook(c, id));
      if (!book) notFound();
      return sendJson(res, 200, book);
    }
    if (method === 'PATCH') {
      const input = await readBody(req, {});
      const book = await patchBook(id, input);
      if (book === null) return sendJson(res, 204);
      return sendJson(res, 200, book);
    }
    fail(405, 'method not allowed');
  }

  if (parts[0] === 'purchases' && parts.length <= 2) {
    const customerId = parseId(req.headers['x-customer-id']);
    if (!customerId || !(await customerExists(customerId))) fail(401, 'unauthorized');
    if (parts.length === 1) {
      if (method === 'GET') return sendJson(res, 200, await listPurchases(customerId, sp));
      if (method === 'POST') {
        const lines = parseLines(await readBody(req, undefined));
        return sendJson(res, 201, await createPurchase(customerId, lines));
      }
      fail(405, 'method not allowed');
    }
    if (method !== 'GET') fail(405, 'method not allowed');
    const id = parseId(parts[1]);
    const purchase = id && (await getPurchase(customerId, id));
    if (!purchase) notFound();
    return sendJson(res, 200, purchase);
  }

  if (parts[0] === 'reports' && parts[1] === 'sales' && parts.length === 2) {
    if (method !== 'GET') fail(405, 'method not allowed');
    const csv = await salesReport(sp);
    res.writeHead(200, {
      'Content-Type': 'text/csv; charset=utf-8',
      'Content-Disposition': 'attachment; filename="sales.csv"',
      'Content-Length': Buffer.byteLength(csv),
    });
    return res.end(csv);
  }

  notFound();
}

const server = http.createServer((req, res) => {
  route(req, res).catch((err) => {
    if (err instanceof HttpError) return sendJson(res, err.status, { error: err.message });
    console.error(err);
    return sendJson(res, 500, { error: 'internal error' });
  });
});

server.listen(PORT, () => console.log(`listening on http://localhost:${PORT}`));

